/* BioFeud event console. All event data is local and editable. */
const QUESTIONS=[
 ['Name a technique used to analyse or manipulate DNA.',['PCR|polymerase chain reaction','Gel electrophoresis|electrophoresis','CRISPR-Cas9|CRISPR','Gene insertion or gene transfer|gene transfer|transformation','Plasmid/vector-based genetic engineering|plasmid|vector','Microinjection']],
 ['Name a factor that can affect microbial growth in a bioreactor.',['Temperature','pH','Nutrient availability|nutrients','Oxygen availability or aeration|oxygen|aeration','Pressure','Feedstock or substrate concentration|substrate|feedstock']],
 ['Name a food or drink made using microorganisms.',['Bread','Yoghurt or curd|yogurt|curd','Beer or fermented alcoholic drinks|beer|fermented alcohol','Cheese','Fermented batter, such as idli or dosa batter|idli|dosa batter','Kombucha']],
 ['Name a movie that features biotechnology, genetic engineering, or scientific experimentation.',['Jurassic Park','Spider-Man|spiderman|spider man','The Hulk|hulk','Captain America','Resident Evil','Godzilla']],
 ['Name a common model organism used in biotechnology and genetic research.',['Mouse|mice','E. coli|ecoli|escherichia coli','Yeast','Zebrafish','Drosophila or fruit fly|fruit fly|drosophila','C. elegans|c elegans|elegans']],
 ['Name a piece of equipment you will almost always find on a lab bench.',['Micropipette or pipette|pipette','Microscope','Weighing balance|balance','Conical flask|flask','Beaker','Petri dish|petri']],
 ['If you could genetically modify one thing about a human, what would people most likely choose?',['Slowing ageing|anti ageing|longevity','Improving intelligence or brain function|intelligence','Increasing height|height','Disease resistance or improved immunity|immunity|disease resistance','Changing physical appearance|appearance','Cloning']],
 ['Name something from science fiction that biotechnology might make possible.',['Cloning','Growing replacement organs|replacement organs|lab grown organs','Superhuman strength or enhanced abilities|superhuman','Invisibility','Cryopreservation or suspended animation|cryopreservation|suspended animation','Growing extra limbs|extra limbs']],
 ['Name a problem biotechnology could help solve in the next 20 years.',['Cancer','Antimicrobial resistance|antibiotic resistance|AMR','Alzheimer’s disease|alzheimer disease','Parkinson’s disease|parkinson disease','Plastic pollution|plastics','Climate change or sustainable agriculture|climate|sustainable agriculture']],
 ['Name a protein important in biotechnology.',['Insulin','DNA polymerase or Taq polymerase|polymerase|taq','Haemoglobin|hemoglobin','Green fluorescent protein (GFP)|GFP|green fluorescent','Bovine serum albumin (BSA) or albumin|BSA|albumin','Pepsin']]
].map(([question,answers])=>({question,answers:answers.map((item,i)=>{const [label,...aliases]=item.split('|');return {label,aliases,points:[30,25,20,15,10,5][i]}})}));
const TOPICS=[
 ['Human genetic modification','If we can genetically prevent a disease, choosing not to do so is ethically questionable.'],
 ['GM crops','Genetically modified crops should be prioritised over conventional breeding to address food insecurity.'],
 ['AI and drug discovery','AI-generated drug candidates should receive priority in drug development over candidates discovered through conventional methods.'],
 ['Alternatives to animal testing','Animal testing in biomedical research should be phased out in favour of organoids and organ-on-chip models.'],
 ['Personalised medicine','Personalised medicine is not truly successful if only wealthy patients can afford it.']
];
const COLORS=['#f18bd4','#ff6b00','#ffe443','#06a979','#31a9db','#bb62db','#f14453','#83c84a'];
const DEFAULT={teams:['Team 1','Team 2','Team 3','Team 4','Team 5'].map((name,i)=>({id:`t${i+1}`,name,color:COLORS[i],r1:0,present:0,question:0})),phase:'setup',q:0,assignments:{},revealed:{},strikes:0,turnEnded:false,round1Done:false,activeTeam:null, audienceEnabled:true,audienceBonus:10,buzzer:null,prep:{remaining:900,running:false},presentation:{index:0,stage:'ready',remaining:60,slots:[],allowDouble:false},topicAssignments:{},presentScores:{},questionScores:{},tieWinner:null,points:[30,25,20,15,10,5],sound:false};
const KEY='biofeud-event-state-v1';let state=loadState(),tickHandle=null,toastHandle=null;
function loadState(){try{const x=JSON.parse(localStorage.getItem(KEY));return x&&Array.isArray(x.teams)?{...structuredClone(DEFAULT),...x}:structuredClone(DEFAULT)}catch{return structuredClone(DEFAULT)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function team(id){return state.teams.find(t=>t.id===id)}function questionData(n){const base=QUESTIONS[n],custom=state.questionEdits?.[n];return custom?{...base,...custom,answers:base.answers.map((a,i)=>({...a,...(custom.answers?.[i]||{})}))}:base}function finalists(){const rows=[...state.teams].sort((a,b)=>b.r1-a.r1||a.name.localeCompare(b.name));if(rows.length<=5)return rows;const cutoff=rows[4].r1,top=rows.filter(t=>t.r1>cutoff),tied=rows.filter(t=>t.r1===cutoff);if(tied.length>1){const chosen=tied.find(t=>t.id===state.finalistTieChoice);return chosen?[...top,chosen]:top}return rows.slice(0,5)}
function ranking(){return [...state.teams].sort((a,b)=>total(b)-total(a)||a.name.localeCompare(b.name))}function total(t){return t.r1+t.present+t.question}function fmt(sec){const s=Math.max(0,Math.ceil(sec));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function showToast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>el.classList.remove('show'),2400)}
function confirmBox(title,body,yes,callback){document.querySelector('#dialog-root').innerHTML=`<div class="dialog-backdrop" role="presentation"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${title}</h2><p>${body}</p><div class="control-row"><button class="btn dark" data-dialog-no>Cancel</button><button class="btn" data-dialog-yes>${yes}</button></div></div></div>`;document.querySelector('[data-dialog-no]').onclick=()=>document.querySelector('#dialog-root').innerHTML='';document.querySelector('[data-dialog-yes]').onclick=()=>{document.querySelector('#dialog-root').innerHTML='';callback()};document.querySelector('[data-dialog-no]').focus()}
function scrollTo(id){document.getElementById(id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function draw(){save();document.querySelector('#app').innerHTML=`${hero()}${roundIntro()}${setupSection()}${rulesSection()}${feudSection()}${scoreboardSection()}${hotIntro()}${prepSection()}${hotGameSection()}${finalSection()}${closing()}`;bind();syncTick()}
function hero(){return `<section class="section hero" id="home"><svg class="helix" viewBox="0 0 160 420" aria-hidden="true"><path d="M20 5 C150 75 10 130 140 205 C10 280 150 345 20 415 M140 5 C10 75 150 130 20 205 C150 280 10 345 140 415" fill="none" stroke="#10101b" stroke-width="9"/><g stroke="#10101b" stroke-width="4"><path d="M45 35h70M35 75h90M29 115h102M30 155h100M45 195h70M30 235h100M29 275h102M35 315h90M45 355h70M58 395h44"/></g></svg><div class="orbit"></div><div class="hero-copy"><span class="eyebrow">A live science game show</span><h1 class="display">BioFeud</h1><div class="subtitle">Where Science Meets Society</div><p>An interactive biotechnology challenge where scientific knowledge meets public debate.</p><div class="hero-actions"><button class="btn" data-scroll="setup">Start the Event</button><button class="btn dark" data-scroll="rules">View the Rules</button></div><span class="round-chip">02 Rounds · 10 rapid-fire boards · 5 big questions</span></div></section>`}
function roundIntro(){return `<section class="section pink-section" id="rounds"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Choose your arena</span><h2 class="section-title">Two rounds.<br>One big question.</h2></div><p>Fast answers meet fearless debate. Set up your teams, then let science and society collide.</p></div><div class="grid two"><article class="round-card" data-scroll="feud"><div><span class="num">01</span><h3>BioFeud</h3><b>Think Fast. Name It. Score It.</b><p>A survey-answer challenge across biotechnology, labs, science fiction, and society.</p></div><div><div class="mini-board"><i></i><i></i><i></i><i></i><i></i><i></i></div><span class="meta">10 QUESTION BOARDS · HOST JUDGED</span></div></article><article class="round-card" data-scroll="hot-takes"><div><span class="num">02</span><h3>Hot Takes</h3><b>Big Claims. Better Questions.</b><p>Five teams defend provocative biotechnology statements as the room challenges their reasoning.</p></div><div><div class="mini-board"><i></i><i></i><i></i><i></i><i></i></div><span class="meta">5 TEAM PRESENTATIONS · LIVE Q&A</span></div></article></div></div></section>`}
function setupSection(){return `<section class="section yellow-section" id="setup"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Before the doors open</span><h2 class="section-title">Team<br>line-up</h2></div><p>These sample names are placeholders. Add your real teams, set their colours, and start the event. Scores and game state save on this device.</p></div><div class="game-layout"><div class="panel"><h3>Registered teams <span class="tag">${state.teams.length} teams</span></h3><div id="team-list">${state.teams.map((t,i)=>`<div class="team-row" data-team-row="${t.id}"><input type="color" class="team-swatch" aria-label="${esc(t.name)} colour" value="${t.color}" data-team-color="${t.id}"><input aria-label="Team ${i+1} name" value="${esc(t.name)}" maxlength="32" data-team-name="${t.id}"><span class="meta">#${String(i+1).padStart(2,'0')}</span><button aria-label="Remove ${esc(t.name)}" data-remove-team="${t.id}">×</button></div>`).join('')}</div><div class="control-row"><button class="btn small" data-action="add-team">+ Add team</button><button class="btn small dark" data-action="reset-r1">Reset scores</button></div><p class="small-note">Round 1: 30 / 25 / 20 / 15 / 10 / 5 event points per board · Audience bonus <input class="field" style="width:75px;padding:6px" type="number" min="0" value="${state.audienceBonus}" data-setting="audienceBonus"></p></div><div class="panel"><h3>Host console</h3><p>Launch the game with one click. Teams rotate through Q1–Q10 in registration order. You can manually switch the active team in each question.</p><div class="control-row"><button class="btn" data-action="start">Start / resume event</button><button class="btn dark" data-action="open-host">Open host controls <kbd>H</kbd></button></div><div class="keyhelp"><b>Host shortcuts</b><br><kbd>Space</kbd> timer · <kbd>S</kbd> strike · <kbd>B</kbd> buzzer · <kbd>N</kbd> next · <kbd>H</kbd> host controls · <kbd>Esc</kbd> close</div></div></div></div></section>`}
const RULES=['Teams take turns answering the question assigned to them.','Each team has up to two minutes to answer its question.','Answers must match one of the accepted answers on the hidden board.','The host reveals a tile to award its event points. These are provisional ranks, not survey counts.','An answer outside the list receives a strike. Two strikes end the turn and open the audience opportunity.','When time expires, the audience may attempt the question.','The host judges spoken answers. Correct audience answers earn the configured bonus; incorrect answers lose nothing.','Round 1 points carry forward into Hot Takes.','Hot Takes finalists present; all teams remain eligible to score as questioners.'];
function rulesSection(){return `<section class="section green-section" id="rules"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Quick briefing</span><h2 class="section-title">Game<br>rules</h2></div><p>Keep it moving, keep it fair. Spoken answers are host judged; the board is there to help you award points consistently.</p></div><div class="grid three">${RULES.map((r,i)=>`<article class="rule"><b>${String(i+1).padStart(2,'0')}</b><p>${r}</p></article>`).join('')}</div><div class="control-row"><button class="btn" data-scroll="feud">Go to BioFeud</button></div></div></section>`}
function feudSection(){const q=questionData(state.q),id=state.assignments[state.q]||state.teams[state.q%Math.max(1,state.teams.length)]?.id;const t=team(id);const left=state.r1Timer?.remaining??120;return `<section class="section blue-section" id="feud"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Round one · ${state.round1Done?'Complete':'Active board'}</span><h2 class="section-title">BioFeud</h2></div><div class="status-line"><span class="tag">HOST DECIDES</span><span class="score-chip">${state.q+1} / 10</span></div></div><div class="game-layout"><div class="question-card"><div class="status-line"><span class="qno">Q${state.q+1}</span><label>Active team <select class="field" style="width:auto;display:inline-block" data-assignment>${state.teams.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><h2>${q.question}</h2><div class="answer-grid">${q.answers.map((a,i)=>{const rev=(state.revealed[state.q]||[]).includes(i);return `<button class="answer-tile ${rev?'scored':'covered'}" data-reveal="${i}" ${rev?'aria-label="Revealed: '+esc(a.label)+', '+(state.points[i]??a.points)+' points"':'aria-label="Reveal rank '+(i+1)+' answer"'}><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="answer">${rev?esc(a.label):'?'}</span><span class="pts">${state.points[i]??a.points} PTS</span></button>`}).join('')}</div><p class="small-note">Click a tile when a spoken answer matches. Each tile scores once. Alias hints: ${state.revealed[state.q]?.length?'<b>Host accepts equivalent answers.</b>':'Answer board is concealed.'}</p></div><div><div class="panel"><h3>Turn console ${t?`<span style="color:${t.color}">● ${esc(t.name)}</span>`:''}</h3><div class="timer ${left<=10?'urgent':left<=30?'warning':''}" data-timer-display="r1">${fmt(left)}</div><div class="control-row"><button class="btn small" data-action="r1-toggle">${state.r1Timer?.running?'Pause':'Start'} timer <kbd>Space</kbd></button><button class="btn small dark" data-action="r1-reset">Reset 2:00</button></div><div style="margin-top:15px"><b>Strikes</b> <span class="strike">${state.strikes>=1?'✕':'○'}</span><span class="strike">${state.strikes>=2?'✕':'○'}</span> <b>${state.strikes}/2</b></div><div class="control-row"><button class="btn small pink" data-action="strike">Strike <kbd>S</kbd></button><button class="btn small" data-action="accept">Accept spoken answer</button></div><div class="control-row"><button class="btn small dark" data-action="end-turn">End turn</button><button class="btn small dark" data-action="pass">Pass to audience</button></div></div><div class="panel" style="margin-top:18px;text-align:center"><h3>Audience buzzer</h3><p class="meta">${state.audienceEnabled?'Enabled · host assigns the buzzing team':'Disabled'}</p><button class="buzzer ${state.buzzer?'locked':''}" data-action="buzz" ${!state.audienceOpen?'disabled':''}>${state.buzzer?'BUZZED IN!':'BUZZ IN!'}</button>${state.buzzer?`<p><b>${esc(team(state.buzzer)?.name||'Audience team')} has the floor</b></p>`:`<label class="field-label">Buzzing team<select class="field" data-buzzer-team>${state.teams.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label>`}<div class="control-row"><button class="btn small green" data-action="aud-correct" ${!state.buzzer?'disabled':''}>Correct +${state.audienceBonus}</button><button class="btn small dark" data-action="aud-wrong" ${!state.buzzer?'disabled':''}>Incorrect · no loss</button><button class="btn small outline" data-action="buzz-reset">Reset buzzer</button></div></div><div class="control-row"><button class="btn small" data-action="prev-q">← Previous</button><button class="btn small" data-action="next-q">Next question <kbd>N</kbd></button><button class="btn small dark" data-scroll="scoreboard">Scoreboard</button></div></div></div></div></section>`}
function scoreRows(mode='r1'){const rows=ranking();let prev=null;return `<div class="score-row header"><span>Rank</span><span>Team</span><span>Round 1</span><span>Present</span><span>Questions</span><span>Total</span></div>${rows.map((t,i)=>{const tie=prev&&total(prev)===total(t);prev=t;return `<div class="score-row"><span class="score-rank">${tie?'=':i+1}</span><span class="team-name"><i class="team-swatch" style="background:${t.color};width:25px;height:25px"></i>${esc(t.name)} ${finalists().some(x=>x.id===t.id)?'<span class="tag">Finalist</span>':''}</span><span>${t.r1}</span><span>${t.present}</span><span>${t.question}</span><span>${total(t)}</span></div>`}).join('')}`}
function scoreboardSection(){const sorted=[...state.teams].sort((a,b)=>b.r1-a.r1||a.name.localeCompare(b.name)),tie=sorted.length>5&&sorted[4].r1===sorted[5].r1,tied=tie?sorted.filter(t=>t.r1===sorted[4].r1):[];return `<section class="section pink-section" id="scoreboard"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Round one standings</span><h2 class="section-title">Score<br>board</h2></div><p>Top five qualify for the presenting line-up. Ties share a rank and stay visible for the host to resolve transparently.</p></div>${tie?`<div class="panel" style="margin-bottom:20px"><h3>Tie for the fifth finalist place</h3><p>Choose who takes the last presentation slot. The choice is recorded and can be changed by the host.</p>${tied.map(t=>`<button class="btn small ${state.finalistTieChoice===t.id?"green":""}" data-finalist-tie="${t.id}">${esc(t.name)} · ${t.r1} points ${state.finalistTieChoice===t.id?"✓":""}</button>`).join(" ")}</div>`:""}<div class="panel">${scoreRows()}<p class="small-note">${tie&&!state.finalistTieChoice?"The fifth finalist slot awaits the host tie-break.":"Finalists are selected from Round 1 points."} Any team can still win through Round 2 question points.</p></div><div class="control-row"><button class="btn" data-scroll="hot-takes">Continue to Hot Takes</button><button class="btn dark" data-action="finish-r1">Mark Round 1 complete</button></div></div></section>`}
function hotIntro(){return `<section class="section orange-section" id="hot-takes"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Round two</span><h2 class="section-title">Hot Takes</h2><h3 style="font:28px var(--display)">Big Claims. Better Questions.</h3></div><p>Biotechnology can transform society—but should it? Make your case, challenge the evidence, and defend your reasoning.</p></div><div class="grid three">${TOPICS.map((t,i)=>`<article class="topic"><div class="n">0${i+1}</div><h3>${t[0]}</h3><blockquote>“${t[1]}”</blockquote></article>`).join('')}</div><div class="panel" style="margin-top:24px"><h3>Finalist topic assignments</h3><div class="grid two">${finalists().map((t,i)=>`<label class="field-label">${esc(t.name)} <select class="field" data-topic-team="${t.id}">${TOPICS.map((x,j)=>`<option value="${j}" ${(state.topicAssignments[t.id]??i)===j?'selected':''}>Topic ${j+1}: ${x[0]}</option>`).join('')}</select></label>`).join('')}</div><p class="small-note">Host can swap topics before or during presentations. All five prompts remain visible during prep.</p><div class="control-row"><button class="btn dark" data-scroll="prep">Enter 15-minute preparation room</button></div></div></div></section>`}
function prepSection(){return `<section class="section yellow-section" id="prep"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Everyone prepares together</span><h2 class="section-title">The prep<br>room</h2></div><div><div class="timer ${state.prep.remaining<=10?'urgent':state.prep.remaining<=30?'warning':''}" data-timer-display="prep">${fmt(state.prep.remaining)}</div><div class="control-row"><button class="btn small" data-action="prep-toggle">${state.prep.running?'Pause':'Start'} prep</button><button class="btn small dark" data-action="prep-reset">Reset 15:00</button></div></div></div><p>Research evidence, prepare arguments, and consider counterarguments. Teams may use the internet; the game itself does not need it.</p><div class="grid three">${TOPICS.map((t,i)=>`<article class="topic"><div class="n">0${i+1}</div><h3>${t[0]}</h3><blockquote>“${t[1]}”</blockquote></article>`).join('')}</div><div class="control-row"><button class="btn dark" data-action="prep-complete">Preparation complete — Begin presentations</button></div></div></section>`}
function hotGameSection(){const fs=finalists();if(!fs.length)return '';const ix=Math.min(state.presentation.index,fs.length-1),presenter=fs[ix],topicIx=state.topicAssignments[presenter?.id]??ix,topic=TOPICS[topicIx]||TOPICS[0],pres=state.presentation,left=pres.remaining;return `<section class="section ink-section" id="presentation"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Hot Takes · presentation ${ix+1} of ${fs.length}</span><h2 class="section-title">The floor<br>is yours.</h2></div><div class="status-line"><span class="speaker" style="background:${presenter?.color}">${esc(presenter?.name||'No finalist')}</span><span>${topic[0]}</span></div></div><div class="game-layout"><div class="topic"><span class="tag">Assigned hot take · Topic ${topicIx+1}</span><h2 style="font:clamp(27px,3.5vw,48px)/1.08 var(--display)">“${topic[1]}”</h2><p>Collaborative opening statement · maximum 60 seconds</p></div><div class="panel"><h3>${stageTitle(pres.stage)}</h3><div class="timer ${left<=10?'urgent':left<=30?'warning':''}" data-timer-display="hot">${fmt(left)}</div><div class="control-row"><button class="btn small" data-action="hot-toggle">${pres.running?'Pause':'Start'} timer</button><button class="btn small dark" data-action="hot-reset">Reset phase timer</button></div>${pres.stage==='ready'?`<div class="control-row"><button class="btn" data-action="opening">Start opening statement</button></div>`:''}${pres.stage==='opening'?`<div class="control-row"><button class="btn pink" data-action="open-questions">Opening done — open question buzzer</button></div>`:''}${pres.stage==='buzz'?buzzSlots(fs,presenter):''}${pres.stage==='qa'?qaControls(fs,presenter):''}${pres.stage==='score'?scoringPanel(fs,presenter):''}${pres.stage==='done'?`<div><b>Presentation scored.</b><div class="control-row"><button class="btn" data-action="next-pres">Next presentation →</button><button class="btn dark" data-scroll="results">Final results</button></div></div>`:''}</div></div><div class="control-row"><button class="btn small outline" data-action="prev-pres">← Previous</button><button class="btn small" data-scroll="results">Live scoreboard</button><button class="btn small" data-action="manual-finish">Finish Hot Takes</button></div></div></section>`}
function stageTitle(s){return ({ready:'Presenter ready',opening:'Opening statement',buzz:'Questioner buzzer',qa:'Two questions · 45 seconds total',score:'Host scoring',done:'Round complete'})[s]||'Presentation'}
function buzzSlots(fs,presenter){const p=state.presentation,eligible=state.teams.filter(t=>t.id!==presenter?.id);return `<p>First two eligible teams to buzz receive question slots. Host confirms order. A team can take one slot unless the host enables a second.</p><label><input type="checkbox" data-setting="allowDouble" ${p.allowDouble?'checked':''}> Allow one team to take both slots</label><label class="field-label">Buzzer team<select class="field" data-questioner-select>${eligible.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><button class="buzzer" data-action="hot-buzz">BUZZ FOR A QUESTION</button><div class="slot"><b>QUESTION SLOT 1</b> ${p.slots[0]?esc(team(p.slots[0])?.name):'Waiting for first buzzer'}</div><div class="slot"><b>QUESTION SLOT 2</b> ${p.slots[1]?esc(team(p.slots[1])?.name):'Waiting for second buzzer'}</div><div class="control-row"><button class="btn small dark" data-action="undo-buzz">Undo last buzz</button><button class="btn" data-action="confirm-slots" ${p.slots.length<2?'disabled':''}>Confirm questioners →</button></div>`}
function qaControls(fs,presenter){const p=state.presentation;return `<p>The presenter has 45 seconds total for both answers. Questioners are scored independently on their question.</p><div class="slot"><b>QUESTION 1</b> ${esc(team(p.slots[0])?.name||'')}${p.asked?.[0]?' · ASKED':''} <button class="btn small" data-asked="0">Mark asked</button></div><div class="slot"><b>QUESTION 2</b> ${esc(team(p.slots[1])?.name||'')}${p.asked?.[1]?' · ASKED':''} <button class="btn small" data-asked="1">Mark asked</button></div><div class="control-row"><button class="btn" data-action="qa-finish">Finish answering → score</button></div>`}
function scoringPanel(fs,presenter){const slots=state.presentation.slots;return `<div class="grid two"><div><h4>Presenting team · max 15</h4>${rubric(presenter?.id,'present',['Scientific accuracy and evidence', 'Relevance and directness', 'Reasoning and complexity', 'Clarity and structure'],[5,4,3,3])}<b>Presenter total: <span data-total="present">0</span> / 15</b><button class="btn small green" data-action="save-present">Save presenter score</button></div>${slots.map((id,i)=>`<div><h4>Questioner ${i+1} · max 8</h4>${rubric(id,`question-${i}`,['Relevance to hot take','Scientific depth and critical thinking','Clarity and precision'],[3,3,2])}<b>Question score: <span data-total="question-${i}">0</span> / 8</b><button class="btn small green" data-action="save-question" data-index="${i}">Save questioner score</button></div>`).join('')}</div><div class="control-row"><button class="btn" data-action="scores-done">Finish scoring →</button></div>`}
function rubric(id,key,labels,max){const saved=key==='present'?state.presentScores[state.presentation.index]:state.questionScores[`${state.presentation.index}:${key}`];return labels.map((label,i)=>`<label class="rubric-row">${label} <input data-score="${key}" data-id="${id}" data-rubric="${i}" type="number" min="0" max="${max[i]}" value="${saved?.[i]??0}"></label>`).join('')}
function finalSection(){const rows=ranking(),top=rows[0],tie=rows[1]&&total(rows[1])===total(top);return `<section class="section blue-section" id="results"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">Final results · live event totals</span><h2 class="section-title">The final<br>word</h2></div><p>Round 1 scores carry forward. Presenters and questioners both score; all teams can claim the win.</p></div>${top?`<div class="win-card"><span class="eyebrow">${tie&&!state.tieWinner?'Tie — host tie-break required':'The winner is'}</span><h2>${tie&&!state.tieWinner?'TIE GAME':esc(team(state.tieWinner)?.name||top.name)}</h2><div class="winner">${tie&&!state.tieWinner?'Choose a tie-break below':`${total(team(state.tieWinner)||top)} POINTS`}</div>${tie&&!state.tieWinner?`<div class="control-row" style="justify-content:center">${rows.filter(t=>total(t)===total(top)).map(t=>`<button class="btn" data-tie="${t.id}">Select ${esc(t.name)} as tie-break winner</button>`).join('')}</div>`:''}</div>`:''}<div class="panel" style="margin-top:24px">${scoreRows('final')}<p class="small-note">Breakdown: Round 1 · Presenting · Questioning · Total event points. Edit scores from the host controls.</p></div><div class="control-row"><button class="btn" data-action="finish-hot">View final results</button><button class="btn dark" data-action="export">Export event JSON</button><button class="btn pink" data-action="restart">Restart event</button></div></div></section>`}
function closing(){return `<section class="section closing" id="closing"><div class="section-inner"><span class="eyebrow">BioFeud · Where Science Meets Society</span><h2>I hope you<br>had fun!</h2><p style="font-size:clamp(17px,2vw,25px);max-width:800px;margin:25px auto">Science is more than what we discover. It’s what we question, communicate, and choose to do with it.</p><button class="btn" data-scroll="home">Back to the beginning ↑</button></div></section><footer class="footer"><span>BIOFEUD · HOST CONSOLE</span><span>Saved on this device · Offline-ready</span></footer>`}
function bind(){
 document.querySelectorAll('[data-scroll]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();scrollTo(el.dataset.scroll)}));
 document.querySelectorAll('.round-card').forEach(el=>el.addEventListener('click',()=>scrollTo(el.dataset.scroll)));
 document.querySelectorAll('[data-team-name]').forEach(el=>el.addEventListener('change',()=>{const t=team(el.dataset.teamName);if(t){t.name=el.value.trim()||'Team';draw()}}));
 document.querySelectorAll('[data-team-color]').forEach(el=>el.addEventListener('input',()=>{const t=team(el.dataset.teamColor);if(t){t.color=el.value;save()}}));
 document.querySelectorAll('[data-remove-team]').forEach(el=>el.onclick=()=>confirmBox('Remove team?','This team and its scores will be removed from the event.','Remove team',()=>{state.teams=state.teams.filter(t=>t.id!==el.dataset.removeTeam);draw()}));
 document.querySelectorAll('[data-setting="audienceBonus"]').forEach(el=>el.onchange=()=>{state.audienceBonus=Math.max(0,Number(el.value)||0);save()});
 document.querySelectorAll('[data-topic-team]').forEach(el=>el.onchange=()=>{state.topicAssignments[el.dataset.topicTeam]=Number(el.value);save()});
 document.querySelectorAll('[data-assignment]').forEach(el=>el.onchange=()=>{state.assignments[state.q]=el.value;state.activeTeam=el.value;save();draw()});
 document.querySelectorAll('[data-reveal]').forEach(el=>el.onclick=()=>reveal(Number(el.dataset.reveal)));
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el));
 document.querySelectorAll('[data-asked]').forEach(el=>el.onclick=()=>{state.presentation.asked=state.presentation.asked||[];state.presentation.asked[Number(el.dataset.asked)]=true;save();draw()});
 document.querySelectorAll('[data-buzzer-team]').forEach(el=>el.onchange=()=>{state.pendingBuzzer=el.value;save()});
 document.querySelectorAll('[data-questioner-select]').forEach(el=>el.onchange=()=>{state.pendingQuestioner=el.value;save()});
 document.querySelectorAll('[data-score]').forEach(el=>el.oninput=()=>{const arr=readRubric(el.dataset.score,el.dataset.id,el.dataset.rubric);const key=el.dataset.score==='present'?'present':el.dataset.score;const dest=document.querySelector(`[data-total="${key}"]`);if(dest)dest.textContent=arr.reduce((a,b)=>a+b,0)});
 document.querySelectorAll('[data-tie]').forEach(el=>el.onclick=()=>{state.tieWinner=el.dataset.tie;save();draw()});document.querySelectorAll('[data-finalist-tie]').forEach(el=>el.onclick=()=>{state.finalistTieChoice=el.dataset.finalistTie;save();draw()});
 document.querySelectorAll('[data-dialog-no]').forEach(el=>el.onclick=()=>document.querySelector('#dialog-root').innerHTML='');
}
function readRubric(key,id,index){const selector=key==='present'?'[data-score="present"]':'[data-score="'+key+'"][data-id="'+id+'"]';const inputs=[...document.querySelectorAll(selector)];return inputs.map(el=>Math.min(Number(el.max)||99,Math.max(0,Number(el.value)||0)))}
function addScore(id,kind,n){const t=team(id);if(!t)return;t[kind]+=n;showToast(`${t.name} +${n} points`)}
function reveal(i){const q=questionData(state.q),rev=state.revealed[state.q]||(state.revealed[state.q]=[]);if(rev.includes(i)){showToast('That answer has already scored.');return}rev.push(i);const id=state.assignments[state.q]||state.teams[state.q%state.teams.length]?.id;const t=team(id);if(t)t.r1+=state.points[i]??q.answers[i].points;state.activeTeam=id;showToast(`${t?.name||'Team'} +${state.points[i]??q.answers[i].points} points`);draw()}
function acceptSpoken(){const old=document.querySelector('#dialog-root');old.innerHTML=`<div class="dialog-backdrop"><div class="dialog" role="dialog" aria-modal="true"><h2>Accept spoken answer</h2><p>Host decides. Type a brief note if useful; choose the board tile to award, or accept it as a correct off-board answer with no automatic points.</p><input class="field" id="spoken-answer" placeholder="Spoken answer / host note" aria-label="Spoken answer"><div class="grid three" style="margin-top:14px">${QUESTIONS[state.q].answers.map((a,i)=>`<button class="btn small" data-accept-tile="${i}">${i+1}. ${esc(a.label)} · ${state.points[i]??a.points}</button>`).join('')}</div><div class="control-row"><button class="btn dark" data-accept-no-points>Accept · no board points</button><button class="btn outline" data-accept-cancel>Cancel</button></div></div></div>`;old.querySelector('[data-accept-cancel]').onclick=()=>old.innerHTML='';old.querySelector('[data-accept-no-points]').onclick=()=>{old.innerHTML='';showToast('Answer accepted by host. No board tile awarded.');};old.querySelectorAll('[data-accept-tile]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.acceptTile),rev=state.revealed[state.q]||(state.revealed[state.q]=[]);old.innerHTML='';if(rev.includes(i)){showToast('That answer already scored.');return}reveal(i)})}
function strike(){if(state.turnEnded)return;state.strikes=Math.min(2,state.strikes+1);if(state.strikes>=2){state.turnEnded=true;state.audienceOpen=true;state.r1Timer={remaining:state.r1Timer?.remaining??120,running:false};showToast('Second strike — audience turn is open.')}else showToast('Strike 1 of 2');draw()}
function setR1Timer(remaining,running){state.r1Timer={remaining,running};save()}
function goQuestion(n){state.q=Math.max(0,Math.min(9,n));state.strikes=0;state.turnEnded=false;state.audienceOpen=false;state.buzzer=null;setR1Timer(120,false);const id=state.assignments[state.q]||state.teams[state.q%Math.max(1,state.teams.length)]?.id;state.assignments[state.q]=id;state.activeTeam=id;draw();scrollTo('feud')}
function stopAudience(){state.turnEnded=true;state.r1Timer.running=false;state.r1Timer.remaining=state.r1Timer.remaining??120;state.audienceOpen=true;draw()}
function action(a,el){const p=state.presentation;
 switch(a){case'add-team':{const n=state.teams.length+1;state.teams.push({id:`t${Date.now()}`,name:`Team ${n}`,color:COLORS[(n-1)%COLORS.length],r1:0,present:0,question:0});draw();break}
 case'start':{if(!state.teams.length){showToast('Add at least one team first.');return}if(!state.assignments[0])state.teams.forEach((t,i)=>{state.assignments[i]=t.id});state.phase='r1';state.round1Done=false;if(!state.r1Timer)state.r1Timer={remaining:120,running:false};draw();scrollTo('feud');break}
 case'reset-r1':confirmBox('Reset Round 1 scores?','This clears Round 1 points, revealed tiles, strikes, and the question timer.','Reset scores',()=>{state.teams.forEach(t=>t.r1=0);state.revealed={};state.q=0;state.strikes=0;state.turnEnded=false;state.r1Timer={remaining:120,running:false};draw()});break;
 case'r1-toggle':state.r1Timer=state.r1Timer||{remaining:120,running:false};state.r1Timer.running=!state.r1Timer.running;save();draw();break;
 case'r1-reset':confirmBox('Reset question timer?','The timer will return to 02:00.','Reset timer',()=>{setR1Timer(120,false);draw()});break;
 case'strike':strike();break;case'accept':acceptSpoken();break;
 case'end-turn':case'pass':stopAudience();showToast('Audience may attempt this question.');break;
 case'prev-q':goQuestion(state.q-1);break;case'next-q':if(state.q<9)goQuestion(state.q+1);else{state.round1Done=true;draw();scrollTo('scoreboard')}break;
 case'buzz':if(!state.audienceEnabled){showToast('Audience buzzer disabled in host controls.');return}if(!state.audienceOpen){showToast('Open the audience turn first.');return}if(state.buzzer){showToast('Buzzer is locked.');return}state.buzzer=state.pendingBuzzer||state.teams[0]?.id;showToast(`${team(state.buzzer)?.name||'Audience'} buzzed in!`);draw();break;
 case'aud-correct':if(!state.buzzer)return;addScore(state.buzzer,'r1',state.audienceBonus);state.buzzer=null;state.audienceOpen=false;draw();break;case'aud-wrong':if(!state.buzzer)return;showToast('No score change.');state.buzzer=null;draw();break;case'buzz-reset':state.buzzer=null;draw();break;
 case'finish-r1':state.round1Done=true;draw();showToast('Round 1 marked complete.');break;
 case'prep-toggle':state.prep.running=!state.prep.running;save();draw();break;case'prep-reset':confirmBox('Reset preparation timer?','The timer will return to 15:00.','Reset timer',()=>{state.prep={remaining:900,running:false};draw()});break;
 case'prep-complete':state.prep.running=false;state.presentation.index=0;state.presentation.stage='ready';state.presentation.remaining=60;draw();scrollTo('presentation');break;
 case'opening':p.stage='opening';p.remaining=60;p.running=true;draw();break;
 case'open-questions':p.stage='buzz';p.remaining=0;p.running=false;p.slots=[];draw();break;
 case'hot-buzz':{const id=state.pendingQuestioner||document.querySelector('[data-questioner-select]')?.value;if(!id)return;if(!p.allowDouble&&p.slots.includes(id)){showToast('That team already has a question slot.');return}if(p.slots.length>=2){showToast('Both question slots are filled.');return}p.slots.push(id);showToast(`${team(id)?.name} takes slot ${p.slots.length}`);draw();break}
 case'undo-buzz':p.slots.pop();draw();break;
 case'confirm-slots':if(p.slots.length===2){p.stage='qa';p.remaining=45;p.running=false;p.asked=[];draw()}break;
 case'hot-toggle':if(p.stage==='ready'){showToast('Start the opening statement first.');return}p.running=!p.running;save();draw();break;
 case'hot-reset':confirmBox('Reset phase timer?','This resets the current phase to its starting duration.','Reset timer',()=>{p.remaining=p.stage==='qa'?45:p.stage==='opening'?60:0;p.running=false;draw()});break;
 case'qa-finish':p.running=false;p.stage='score';p.remaining=0;draw();break;
 case'save-present':{const arr=readRubric('present',finalists()[p.index]?.id,0);state.presentScores[p.index]=arr;const t=finalists()[p.index];if(t){t.present=arr.reduce((a,b)=>a+b,0)}showToast('Presenter score saved.');draw();break}
 case'save-question':{const ix=Number(el.dataset.index),id=p.slots[ix],arr=readRubric(`question-${ix}`,id,0);state.questionScores[`${p.index}:question-${ix}`]=arr;const t=team(id);if(t)t.question=Object.values(state.questionScores).reduce((sum,x)=>sum+x.reduce((a,b)=>a+b,0),0);showToast('Questioner score saved.');draw();break}
 case'scores-done':p.stage='done';p.running=false;draw();break;
 case'next-pres':if(p.index<finalists().length-1){p.index++;p.stage='ready';p.remaining=60;p.slots=[];p.asked=[];p.running=false;draw();scrollTo('presentation')}else{p.stage='done';draw();scrollTo('results')}break;
 case'prev-pres':if(p.index>0){p.index--;p.stage='ready';p.remaining=60;p.slots=[];draw()}break;case'manual-finish':confirmBox('Finish Hot Takes?','This closes the current presentation sequence and shows final standings.','Finish round',()=>{p.stage='done';p.running=false;draw();scrollTo('results')});break;
 case'finish-hot':scrollTo('results');break;
 case'export':exportData();break;case'restart':confirmBox('Restart the whole event?','All team scores, topic assignments, question reveals, and timer state will be cleared. Team names and colours stay in place.','Restart event',()=>{const teams=state.teams.map(t=>({...t,r1:0,present:0,question:0}));state=structuredClone(DEFAULT);state.teams=teams;save();draw();scrollTo('home')});break;
 case'open-host':toggleHost(true);break;
 }
}
function exportData(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`biofeud-event-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast('Event data exported.')}
function toggleHost(force){const d=document.querySelector('#host-drawer');if(force===true)d.hidden=false;else d.hidden=!d.hidden;if(!d.hidden){renderDrawer();document.querySelector('#host-shade').hidden=false;d.querySelector('[data-host-close]')?.focus()}else{document.querySelector('#host-shade').hidden=true}}
function hostAnswerEditor(){const q=questionData(state.q);return `<h3 style="margin-top:28px">Edit current board · Q${state.q+1}</h3><label class="field-label">Question<input class="field" data-edit-question value="${esc(q.question)}"></label>${q.answers.map((a,i)=>`<label class="field-label">Rank ${i+1} answer<input class="field" data-edit-label="${i}" value="${esc(a.label)}"><span class="meta">Aliases, comma separated</span><input class="field" data-edit-alias="${i}" value="${esc(a.aliases.join(', '))}"></label>`).join('')}<button class="btn small" data-save-board>Save question and answers</button>`}
function renderDrawer(){const d=document.querySelector('#host-drawer');d.innerHTML=`<div class="drawer-top"><h2>Host controls</h2><button class="close" data-host-close aria-label="Close host controls">×</button></div><p>Compact controls for the person running the room. Changes save automatically to this browser.</p><label class="field-label"><input type="checkbox" data-host-setting="audienceEnabled" ${state.audienceEnabled?'checked':''}> Enable audience buzzer</label><label class="field-label"><input type="checkbox" data-host-setting="sound" ${state.sound?'checked':''}> Sound alerts (visual-only build; browser chime)</label><h3>Answer rank points</h3>${state.points.map((n,i)=>`<label class="rubric-row">Rank ${i+1} <input type="number" min="0" data-point="${i}" value="${n}"></label>`).join('')}<button class="btn small" data-host-save-points>Save point values</button>${hostAnswerEditor()}<h3 style="margin-top:28px">Score corrections</h3>${state.teams.map(t=>`<div class="panel" style="margin:10px 0;padding:12px"><b>${esc(t.name)}</b><label class="rubric-row">Round 1 <input type="number" min="0" data-correct="${t.id}" data-kind="r1" value="${t.r1}"></label><label class="rubric-row">Presenting <input type="number" min="0" data-correct="${t.id}" data-kind="present" value="${t.present}"></label><label class="rubric-row">Questioning <input type="number" min="0" data-correct="${t.id}" data-kind="question" value="${t.question}"></label><button class="btn small" data-save-correction="${t.id}">Save correction</button></div>`).join('')}<h3 style="margin-top:28px">Event data</h3><div class="control-row"><button class="btn small" data-host-export>Export JSON</button><button class="btn small dark" data-host-import>Import JSON</button><input type="file" accept="application/json,.json" hidden id="import-file"><button class="btn small pink" data-host-reset>Reset all event data</button></div><div class="keyhelp"><b>Shortcuts</b><br><kbd>Space</kbd> timer · <kbd>S</kbd> strike · <kbd>B</kbd> buzzer · <kbd>N</kbd> next · <kbd>H</kbd> controls · <kbd>Esc</kbd> close</div>`;
 d.querySelector('[data-host-close]').onclick=()=>toggleHost(false);d.querySelectorAll('[data-host-setting]').forEach(el=>el.onchange=()=>{state[el.dataset.hostSetting]=el.checked;save();if(el.dataset.hostSetting==='audienceEnabled')draw()});d.querySelector('[data-host-save-points]').onclick=()=>{state.points=[...d.querySelectorAll('[data-point]')].map(x=>Math.max(0,Number(x.value)||0));draw();renderDrawer();showToast('Rank points updated.')};d.querySelector('[data-save-board]').onclick=()=>{const n=state.q,question=d.querySelector('[data-edit-question]').value;state.questionEdits=state.questionEdits||{};const previous=state.questionEdits[n]||{answers:[]};const answers=QUESTIONS[n].answers.map((a,i)=>({label:d.querySelector(`[data-edit-label="${i}"]`).value.trim()||a.label,aliases:d.querySelector(`[data-edit-alias="${i}"]`).value.split(',').map(x=>x.trim()).filter(Boolean)}));state.questionEdits[n]={...previous,question:question.trim()||QUESTIONS[n].question,answers};draw();renderDrawer();showToast('Question board saved.')};d.querySelectorAll('[data-save-correction]').forEach(b=>b.onclick=()=>{const t=team(b.dataset.saveCorrection);for(const x of d.querySelectorAll(`[data-correct="${t.id}"]`))t[x.dataset.kind]=Math.max(0,Number(x.value)||0);draw();renderDrawer();showToast(`${t.name} score corrected.`)});d.querySelector('[data-host-export]').onclick=exportData;d.querySelector('[data-host-import]').onclick=()=>d.querySelector('#import-file').click();d.querySelector('#import-file').onchange=e=>{const f=e.target.files?.[0];if(f)importFile(f)};d.querySelector('[data-host-reset]').onclick=()=>confirmBox('Reset all event data?','This clears team names, colours, scores, progress, assignments, reveals, and timers.','Reset everything',()=>{state=structuredClone(DEFAULT);draw();toggleHost(false);scrollTo('home')});}
function importFile(file){const reader=new FileReader();reader.onload=()=>{try{const raw=JSON.parse(reader.result),incoming=raw.state||raw;if(!incoming||!Array.isArray(incoming.teams)||incoming.teams.some(t=>typeof t.name!=='string'||!Number.isFinite(Number(t.r1))||!Number.isFinite(Number(t.present))||!Number.isFinite(Number(t.question))))throw Error('Invalid team data');if(incoming.teams.length>50)throw Error('Too many teams');confirmBox('Import event data?','Valid event JSON found. Import will replace the current session on this device.','Import data',()=>{state={...structuredClone(DEFAULT),...incoming,teams:incoming.teams.map(t=>({...t,id:String(t.id||`t${Math.random()}`),name:t.name.slice(0,32),color:/^#[0-9a-f]{6}$/i.test(t.color)?t.color:COLORS[0],r1:Number(t.r1)||0,present:Number(t.present)||0,question:Number(t.question)||0}))};draw();toggleHost(false);showToast('Event data imported.')})}catch(err){showToast(`Could not import: ${err.message}`)}};reader.readAsText(file)}
function tone(){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext,c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=660;g.gain.setValueAtTime(.12,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.65);o.start();o.stop(c.currentTime+.65);o.onended=()=>c.close()}catch{}}
function expire(which){tone();if(which==='r1'){state.r1Timer={remaining:0,running:false};state.turnEnded=true;state.audienceOpen=true;state.buzzer=null;showToast('Time! Audience may attempt the question.');draw()}else if(which==='prep'){state.prep={remaining:0,running:false};showToast('Preparation time is up.');draw()}else if(which==='hot'){const p=state.presentation;p.remaining=0;p.running=false;if(p.stage==='opening'){p.stage='buzz';p.slots=[];showToast('Opening statement time is up. Open the question buzzer.')}else if(p.stage==='qa'){p.stage='score';showToast('Shared answer time is up. Score the contributions.')}draw()}}
function syncTick(){if(tickHandle)clearInterval(tickHandle);tickHandle=setInterval(()=>{let changed=false;const now=Date.now();if(state.r1Timer?.running){const left=Math.max(0,(state.r1Timer.deadline-now)/1000);state.r1Timer.remaining=left;if(left<=0){expire('r1');return}changed=true}if(state.prep.running){const left=Math.max(0,(state.prep.deadline-now)/1000);state.prep.remaining=left;if(left<=0){expire('prep');return}changed=true}const p=state.presentation;if(p.running){const left=Math.max(0,(p.deadline-now)/1000);p.remaining=left;if(left<=0){expire('hot');return}changed=true}if(changed){document.querySelectorAll('[data-timer-display="r1"]').forEach(el=>{el.textContent=fmt(state.r1Timer.remaining);el.classList.toggle('warning',state.r1Timer.remaining<=30&&state.r1Timer.remaining>10);el.classList.toggle('urgent',state.r1Timer.remaining<=10)});document.querySelectorAll('[data-timer-display="prep"]').forEach(el=>{el.textContent=fmt(state.prep.remaining);el.classList.toggle('warning',state.prep.remaining<=30&&state.prep.remaining>10);el.classList.toggle('urgent',state.prep.remaining<=10)});document.querySelectorAll('[data-timer-display="hot"]').forEach(el=>{el.textContent=fmt(p.remaining);el.classList.toggle('warning',p.remaining<=30&&p.remaining>10);el.classList.toggle('urgent',p.remaining<=10)});save()}},200)}
function startTimer(timer){timer.deadline=Date.now()+timer.remaining*1000;timer.running=true}function pauseTimer(timer){timer.remaining=Math.max(0,(timer.deadline-Date.now())/1000);timer.running=false;delete timer.deadline}
document.addEventListener('click',e=>{if(e.target.id==='host-open')toggleHost();if(e.target.id==='host-shade')toggleHost(false)});
document.addEventListener('keydown',e=>{const typing=e.target.matches('input,textarea,select,[contenteditable="true"]');if(e.key==='Escape'){document.querySelector('#dialog-root').innerHTML='';if(!document.querySelector('#host-drawer').hidden)toggleHost(false);return}if(typing||e.target.matches('button,a')||e.ctrlKey||e.metaKey||e.altKey)return;const active=[...document.querySelectorAll('main section')].sort((a,b)=>Math.abs(a.getBoundingClientRect().top)-Math.abs(b.getBoundingClientRect().top))[0]?.id;if(e.key.toLowerCase()==='h'){toggleHost();return}if(e.code==='Space'){e.preventDefault();if(active==='prep')action('prep-toggle');else if(active==='presentation')action('hot-toggle');else action('r1-toggle');return}if(e.key.toLowerCase()==='s'&&active==='feud')action('strike');if(e.key.toLowerCase()==='b'&&active==='feud')action('buzz');if(e.key.toLowerCase()==='n'&&active==='feud')action('next-q')});
// Keep a single deadline-based timer per active phase. Values are derived from wall-clock deadlines,
// so a background tab or React-free rerender cannot make the clock drift.
const _action=action;action=function(a,el){const p=state.presentation;const adjust=(timer,running)=>{if(running){if(timer!==state.r1Timer&&state.r1Timer?.running)pauseTimer(state.r1Timer);if(timer!==state.prep&&state.prep?.running)pauseTimer(state.prep);if(timer!==p&&p.running)pauseTimer(p);startTimer(timer)}else pauseTimer(timer)};if(a==='r1-toggle'){state.r1Timer=state.r1Timer||{remaining:120,running:false};adjust(state.r1Timer,!state.r1Timer.running);save();draw();return}if(a==='prep-toggle'){adjust(state.prep,!state.prep.running);save();draw();return}if(a==='hot-toggle'){if(p.stage==='ready'){showToast('Start the opening statement first.');return}adjust(p,!p.running);save();draw();return}if(a==='r1-reset'){confirmBox('Reset question timer?','The timer will return to 02:00.','Reset timer',()=>{state.r1Timer={remaining:120,running:false};draw()});return}if(a==='prep-reset'){confirmBox('Reset preparation timer?','The timer will return to 15:00.','Reset timer',()=>{state.prep={remaining:900,running:false};draw()});return}if(a==='hot-reset'){confirmBox('Reset phase timer?','The timer will return to the current phase duration.','Reset timer',()=>{p.remaining=p.stage==='qa'?45:p.stage==='opening'?60:0;p.running=false;draw()});return}if(a==='opening'){if(state.r1Timer?.running)pauseTimer(state.r1Timer);if(state.prep.running)pauseTimer(state.prep);p.stage='opening';p.remaining=60;startTimer(p);draw();return}if(a==='confirm-slots'){if(p.slots.length===2){p.stage='qa';p.remaining=45;p.running=false;delete p.deadline;p.asked=[];draw()}return}if(a==='qa-finish'){p.running=false;delete p.deadline;p.stage='score';p.remaining=0;draw();return}if(a==='open-questions'){p.stage='buzz';p.remaining=0;p.running=false;delete p.deadline;p.slots=[];draw();return}if(a==='prep-complete'){state.prep.running=false;delete state.prep.deadline;if(state.r1Timer?.running)pauseTimer(state.r1Timer);state.presentation.index=0;state.presentation.stage='ready';state.presentation.remaining=60;draw();scrollTo('presentation');return}if(a==='end-turn'||a==='pass'){state.audienceOpen=true;state.turnEnded=true;state.r1Timer=state.r1Timer||{remaining:120};pauseTimer(state.r1Timer);state.audienceOpen=true;draw();return}if(a==='restart'){confirmBox('Restart the whole event?','All team scores, progress, reveals, and timers will be cleared. Team names and colours stay in place.','Restart event',()=>{const teams=state.teams.map(t=>({...t,r1:0,present:0,question:0}));state=structuredClone(DEFAULT);state.teams=teams;save();draw();scrollTo('home')});return}_action(a,el)};
// Host drawer shade is mounted outside the app so the projected page stays unchanged.
document.body.insertAdjacentHTML('beforeend','<div id="host-shade" class="shade" hidden></div>');
draw();
